insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K102', 'How much does home care cost?', 'Our published rates are Wellness Care $30 an hour, Personal Care $32 an hour, and Advanced Care $34 an hour. Overnight and 24-Hour Care use the same hourly rates, based on the level of care needed. An in-home assessment gives you an exact number for your schedule and needs.', 'hourly_rates', 'S7', array['cost','price','rate','hourly','how much']::text[], array['What are your rates?','How much per hour?','What is the price of care?','How much does a caregiver cost?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
