insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K103', 'What is the minimum number of hours?', 'Scheduled care has a minimum of 4 hours per visit and 8 hours per week. Our Booking App is coming soon for clients. It will let you request Wellness Care visits from 2 hours with no weekly minimum. App visits depend on which caregivers are available, so a request is sent, not guaranteed.', 'minimum_hours', 'S7', array['minimum','hours','per visit','per week']::text[], array['Is there a minimum?','How few hours can we book?','Can we get a short visit?','Do you have a weekly minimum?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
