insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K111', 'Do you provide dementia care?', 'Yes. Advanced Care, $34 an hour, is for advanced Alzheimer''s and other dementias, confusion or wandering, Parkinson''s, stroke-related challenges and significant mobility needs. Caregivers are matched to your loved one. It is still non-medical care, not skilled nursing. Families caring for someone with dementia may also qualify for respite through the Medicare GUIDE program.', 'dementia_care', 'S7', array['dementia','alzheimers','memory','advanced care']::text[], array['Can you help with Alzheimer''s?','My mom has memory problems, can you help?','Do you handle wandering?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
