insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K116', 'How do I apply for a job?', 'We would love to hear from you. You can apply at mo-care.com/apply, it takes about 2 minutes, and then you pick your interview time. We ask for at least one year of paid caregiving experience. Caregivers are W-2 employees with paid training, weekly pay, and full time or part time schedules, mostly in Greene, Christian, Webster and Polk counties.', 'jobs_apply', 'S7', array['job','apply','application','hiring','employment','caregiver','career']::text[], array['Do you have caregiver jobs?','I am interested in overnight or full time caregiver work','I want to work for you','Do you have job openings?','Where is the job application?','I want to be a caregiver','I am interested in employment']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
