insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K117', 'What do I need to be a caregiver with you?', 'We ask for at least one year of paid caregiving experience. Work at home, in a nursing home, assisted living or a hospital counts, and so does being paid to care for a family member. Wellness Care roles need no license. Advanced Care roles are for licensed CNAs. You must be 18 or older and able to work in the United States. For anything else, apply at mo-care.com/apply and we will talk it through.', 'jobs_requirements', 'S7', array['job','requirements','license','cna','experience','diploma']::text[], array['Do I need a CNA license?','Do I need a high school diploma?','What experience do I need?','What are the job requirements?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
