values ('K120', 'Do you have an app?', 'Our Booking App is coming soon for clients. After an in-home assessment and care plan, it lets you request Wellness Care visits, $30 an hour, any day from 7am to 6pm, for 2 hours or more, with no weekly minimum. The app has no charge any month you have a visit, and months without a visit are $15. Visits depend on which caregivers are available, so a request is sent, not guaranteed.', 'booking_app', 'S7', array['app','booking app','book online','phone']::text[], array['How does the Booking App work?','Can I book visits online?','Can I book care from my phone?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
