insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K121', 'Can we choose our caregiver?', 'Every client gets a personalized care plan, and our team works to match your loved one with the right caregiver for their needs. Tell us what matters to your family and we will take it into account. If you are on Medicaid and want to pick your own attendant, that is Consumer Directed Services through our sister company, Caring Companions Consumer Directed Services, at (417) 218-2888 or caringcds.com.', 'choose_caregiver_cc', 'S7', array['choose','caregiver','match','same caregiver']::text[], array['Can my dad choose his caregiver?','Do we get the same caregiver?','How do you pick the caregiver?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
