insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K122', 'We are moving and already have home care, can you take over?', 'If the current care is paid by Medicaid, please reach our sister company, Caring Companions Consumer Directed Services, at (417) 218-2888 or caringcds.com, since Caring Companions does not take Medicaid. If you pay privately, or through VA or long-term care insurance, we can start with an in-home assessment. Call (417) 234-8494 and we will check that your new address is in our area.', 'transfer_agency', 'S7', array['transfer','switch','moved','another agency']::text[], array['He already has in home services and we just relocated','Can we switch to you from another agency?','Our previous company does not have a branch in our new location']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
