insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K123', 'Can caregivers take my mom on outings?', 'Yes. A visit can include an outing, like the library, lunch at a senior center, a garden walk or a local event. The caregiver drives, stays with them the whole time and brings them home. We call it Good Days Out.', 'outings', 'S7', array['outings','activities','get out','senior center']::text[], array['Can a caregiver get him out of the house?','Do you do activities or trips?','What is Good Days Out?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
