insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K124', 'Do you have training for family caregivers?', 'Yes. The Family Care Academy has the same training our caregivers get, rebuilt for families, with no sign-up. The Dementia Journey is a nine-module course for families, narrated by Samantha, and every module is open now. Hands-on care skills lessons are in production.', 'family_academy', 'S7', array['family care academy','training','course','class','dementia journey']::text[], array['Is there a class for families?','What is the Family Care Academy?','Do you have a dementia course for families?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
