insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K125', 'Are your caregivers employees?', 'Yes. Every caregiver is a Caring Companions employee, never a contractor, and we handle their payroll and taxes. Before they start, every caregiver has federal, state and county background checks, a driving record check and verification that they can work, and the checks are repeated over time. Caregivers are bonded and insured, including when they drive clients.', 'caregivers_employees', 'S8', array['employees','insured','bonded','screened','background check']::text[], array['Are caregivers background checked?','Are your caregivers insured and bonded?','Are your caregivers contractors?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
