insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K126', 'Do you match lower prices?', 'Yes, our Best Price Guarantee. If another professional home care agency gives you a lower written rate for comparable care, we will beat it for your first six months. It is for new private-pay clients, and our standard rates apply after six months.', 'price_guarantee', 'S7', array['price match','guarantee','cheaper','beat']::text[], array['Can you beat another agency''s rate?','Do you have a price guarantee?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
