insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K127', 'How long have you been in business?', 'Caring Companions has been family owned in Springfield since 2017. We are locally owned, not a franchise, and when you call our office you reach people right here in southwest Missouri.', 'about_company', 'S7', array['company','since 2017','franchise','locally owned']::text[], array['Are you a franchise?','Who owns Caring Companions?','Tell me about your company']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
