insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K129', 'Do you offer companion care and help around the house?', 'Yes. Wellness Care is $30 an hour, for someone mostly independent who could use company and help around the house. It covers companionship, meal planning and cooking, light housekeeping and laundry, groceries, errands and rides, medication reminders, help with phones and video calls, and pets, plants and mail.', 'wellness_care', 'S7', array['wellness care','companionship','housekeeping','meals','errands','lonely']::text[], array['What is Wellness Care?','Can someone help with meals and errands?','My mom is lonely, can someone visit?','Can you help with housekeeping?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
