insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K132', 'How soon can care start?', 'Before care begins, we complete a free in-home assessment and build a care plan, so your caregivers know your loved one''s needs, routines, preferences and safety. How soon care starts after that depends on how quickly we can complete the assessment and find the right caregiver. Care can sometimes begin the same day or next day, but our office confirms the start once a caregiver is matched. We never want to rush the process at the expense of good care. You can book your free in-home assessment at mo-care.com/book or call (417) 234-8494.', 'start_timing', 'S9', array['start','how soon','quickly','right away']::text[], array['How quickly can you start?','Can care start right away?','How long until a caregiver can come?','We need help as soon as possible','Can you start this week?','How soon can care start after the assessment?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha wrote and approved 11-06', 'na', 'na', 'ok', 1)
