insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K133', 'What happens if our caregiver is sick?', 'Your caregiver calls our office, and we let you know right away. The office works to find another caregiver to cover the visit, but a replacement cannot always be guaranteed. If you chose text updates, your family gets a text with the new caregiver''s profile, so you are never surprised by who is at the door.', 'caregiver_sick', 'S8', array['sick','backup','replacement','call off']::text[], array['What if the caregiver calls in sick?','What if our caregiver cannot make it?','Do you have backup caregivers?','What if the caregiver does not show up?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
