insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K134', 'Is there a contract or a deposit?', 'No deposit and no long-term contract. You are billed weekly, after the visits have happened, from your caregiver''s actual clock-in and clock-out times. Your rate is written in your Client Care Agreement, and we give at least 4 weeks'' written notice before any rate change.', 'contract_deposit', 'S8', array['contract','deposit','commitment']::text[], array['Do we have to sign a long-term contract?','Do you require a deposit?','Is there a commitment?','Are we locked in?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
