insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K135', 'What if we need to cancel a visit?', 'There is no fee to cancel a visit with at least 24 hours'' notice. With less than 24 hours'' notice, the visit is billed at 2 hours, because your caregiver counted on that time for their pay. Please call the office at (417) 234-8494 to cancel a visit.', 'cancel_visit', 'S8', array['cancel','cancellation','visit']::text[], array['Is there a cancellation fee?','Can we cancel a visit?','What is your cancellation policy for a visit?','Can we skip a visit?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
