insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K136', 'How do we stop care?', 'You can end services at any time. If you know about a change ahead of time, the agreement asks for two weeks'' notice so we can plan for your caregivers, and we understand that many times there is no notice at all. Just call the office at (417) 234-8494.', 'end_services', 'S8', array['end services','stop care','discontinue','notice']::text[], array['Can we stop care any time?','How much notice do you need to end care?','What if we no longer need care?','How do we discontinue care?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
