insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K137', 'How does billing work?', 'You get one invoice each week, Monday through Sunday, by email, showing every visit from your caregiver''s clock-in and clock-out times. Autopay then pays it from the card or bank account you keep on file. Credit cards have a 3% processing fee. Debit cards and bank (ACH) payments have no fee.', 'billing', 'S8', array['billing','invoice','autopay','credit card']::text[], array['How often are we billed?','When do we get an invoice?','Can we pay by credit card?','Do you have autopay?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
