insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K138', 'Do you provide care on holidays?', 'Yes. Care on New Year''s Day, Easter Sunday, Memorial Day, Juneteenth, Independence Day, Labor Day, Thanksgiving and Christmas Day is billed at time and a half. If you ask a caregiver to work more than 40 hours in a week, the extra hours are also billed at time and a half.', 'holidays', 'S8', array['holiday','holidays','time and a half','overtime']::text[], array['Do caregivers work on Christmas?','Do you charge more on holidays?','Is there holiday pay?','What about overtime?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
