insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K139', 'Can a caregiver drive Mom to appointments?', 'Yes, in your car or theirs. In your car there is no mileage charge, but your auto insurance must be current. In the caregiver''s car, mileage is billed at $0.69 a mile. Caregivers are bonded and insured, including when they drive clients.', 'rides_appointments', 'S8', array['appointments','doctor','drive','mileage','transportation']::text[], array['Do you provide transportation to the doctor?','Can a caregiver take my dad to dialysis?','Do caregivers drive clients?','Is there a mileage charge?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
