insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K141', 'What can''t caregivers do?', 'Our care is non-medical, so caregivers cannot give medicines, change dressings or do nursing procedures. For everyone''s safety, they also cannot do unsafe lifting, move heavy furniture, climb ladders or stools, or do outdoor maintenance. Everything they do follows your care plan.', 'cannot_do', 'S8', array['not allowed','limits','ladder','furniture','yard work']::text[], array['What are caregivers not allowed to do?','Can a caregiver climb a ladder?','Can caregivers do yard work?','Can caregivers move furniture?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
