values ('K142', 'Can you care for a couple?', 'Yes. Shared household help for a couple is billed at the standard hourly rate. If both people need personal care, dementia care or hands-on supervision, care is billed at 1.5 times the hourly rate.', 'couples', 'S8', array['couple','both','two people']::text[], array['Both of my parents need care','Can one caregiver help my mom and dad?','How much for two people?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
