values ('K143', 'Will we know who is coming?', 'Always. Before the first visit, we send your caregiver''s profile with a friendly photo, so you know who is coming. If your caregiver ever changes, the family members you choose get a text with the new caregiver''s profile.', 'know_who_coming', 'S8', array['who is coming','photo','profile','meet']::text[], array['Can we meet the caregiver first?','Will we see a photo of the caregiver?','Who will be coming to our home?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
