insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K144', 'What if our caregiver is not a good fit?', 'Tell us. We call a few days after the first visit to see how it is going, and you can call us any time before then. Most things can be worked out with a quick change to the care plan. If it still is not right, we will do our best to send a different caregiver.', 'not_good_fit', 'S8', array['good fit','different caregiver','change caregiver']::text[], array['What if we do not like the caregiver?','Can we change caregivers?','Mom does not get along with her caregiver','Can we ask for a different caregiver?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
