insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K145', 'How will we know how the visits are going?', 'Caregivers write a note after every visit. Our office reviews caregiver notes and follows up when something needs attention. If a caregiver has not clocked in a few minutes after a visit should start, our office is alerted right away. The family members you choose can see the care calendar, visit notes and invoices in AxisCare.', 'visit_updates', 'S8', array['updates','notes','informed','axiscare']::text[], array['Will we get updates?','Can we see the caregiver notes?','How do you keep the family informed?','Do caregivers write notes?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
