values ('K146', 'Can we tip our caregiver or give a gift?', 'No gifts or tips, please. Caregivers are not allowed to accept them. A thank-you card, or a call to the office to say thank you, means the world.', 'tips_gifts', 'S8', array['tip','tips','gift','gifts']::text[], array['Can I give the caregiver a gift?','Is tipping allowed?','Can we give our caregiver a present?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
