values ('K147', 'Can we hire our caregiver privately?', 'Every caregiver is a Caring Companions employee, so caregivers cannot be hired privately, even for a few extra hours. This is covered in your Client Care Agreement. If you need more hours, call the office at (417) 234-8494 and we will set them up.', 'hire_privately', 'S8', array['hire privately','pay directly','on the side']::text[], array['Can we pay the caregiver directly?','Can our caregiver work for us on the side?','Can we hire her for a few extra hours ourselves?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
