insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K148', 'What if Mom goes into the hospital?', 'Please call the office as soon as you can so we can pause visits. Before care starts again, we will check the care plan with you, because needs often change after a hospital stay.', 'hospital_pause', 'S8', array['pause','on hold','admitted','hospital']::text[], array['Dad was admitted to the hospital, what about his visits?','Can we pause care?','Can we put visits on hold?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
