values ('K149', 'Can we read your agreement before we decide?', 'Yes. Our Client Handbook and a sample Client Care Agreement are on mo-care.com/before-your-assessment. They are the same documents our clients get, and we go through your agreement with you in person.', 'read_agreement', 'S8', array['agreement','handbook','policies','documents']::text[], array['Can I see a copy of the client agreement?','Do you have a client handbook?','Can we read your policies?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
