insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K150', 'How do I raise a concern or complaint?', 'Call the office any time at (417) 234-8494, or write to us. Every concern goes to the agency administrator. We look into it right away, tell you what we found, and your care continues as normal while we work it out. Still not right? Call Samantha directly. For abuse, neglect or exploitation, you can also call the Missouri hotline at 1-800-392-0210.', 'concerns', 'S8', array['complaint','concern','problem','manager']::text[], array['I have a complaint','Who do I talk to about a problem with our care?','Can I speak to a manager?','I am not happy with our care']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
