insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K151', 'Is it okay if we have pets?', 'Yes. Help with pets is even part of Wellness Care. We ask that any pet that could be aggressive is secured before your caregiver arrives.', 'pets', 'S8', array['pets','dog','cat','animals']::text[], array['We have a dog, is that okay?','Do caregivers mind cats?','Can caregivers help with our pets?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
