insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K152', 'Can someone smoke in the home during visits?', 'We ask for a smoke-free space while your caregiver is there. Caregivers cannot be in the home during active smoking.', 'smoking', 'S8', array['smoking','smoke','cigarettes']::text[], array['My dad smokes, is that a problem?','Do caregivers smoke?','Is smoking allowed?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha approved 11-06 (from mo-care.com, Client Care Agreement, Client Handbook)', 'na', 'na', 'ok', 1)
