insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K153', 'Can care start today or tomorrow?', 'Sometimes! We understand that families may need help quickly, and we will do our best to accommodate urgent requests. Before care begins, we do need to complete a free in-home assessment. This lets us understand your loved one''s needs, routines, preferences and safety, so we can create a personalized care plan for the caregivers we send. Care can sometimes begin the same day or next day, depending on how quickly we can complete the assessment and find the right caregiver. We never want to rush the process at the expense of good care. Call us at (417) 234-8494, and we will talk through what you need and how soon we may be able to get started.', 'start_today', 'S9', array['today','tomorrow','same day','next day','urgent']::text[], array['We need someone today','Can a caregiver come tomorrow?','Do you take same-day requests?','Can you send someone tonight?','We need help urgently today']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha wrote and approved 11-06', 'na', 'na', 'ok', 1)
