insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K154', 'Can you help someone receiving hospice care?', 'Yes! Caring Companions can work alongside your loved one''s hospice team to provide additional non-medical care and support. Our caregivers can help with personal care, bathing, dressing, repositioning within their training and safety limits, companionship and everyday household tasks. We can also provide support during the day or overnight for families who need more help. The hospice team continues to provide medical care, while our caregivers focus on comfort, personal care and helping your loved one stay supported. We coordinate with the family and the hospice team so everyone understands the care plan and their responsibilities.', 'hospice', 'S9', array['hospice','end of life','comfort care']::text[], array['Do you work with hospice?','My mom is on hospice, can you help?','Do you provide end of life care?','Can a caregiver stay with dad while he is on hospice?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha wrote and approved 11-06', 'na', 'na', 'ok', 1)
