values ('K155', 'Do you provide care on weekends?', 'Yes! Caring Companions provides care seven days a week, including weekends and holidays. Whether your family needs a few hours of help, regular weekend visits or overnight care, we can talk through your schedule and check caregiver availability. Certain holidays are billed at a higher hourly rate, and we will explain any charges before care begins.', 'weekends', 'S9', array['weekends','saturday','sunday','seven days']::text[], array['Can a caregiver come on Saturday?','Do you work Sundays?','Are you open 7 days a week?','We need weekend help']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-06', 'Samantha wrote and approved 11-06', 'na', 'na', 'ok', 1)
